/**
 * Components Script
 * logika Shop View dan Product View untuk Alpine.js
 */

// 1. SHOP VIEW COMPONENT LOGIC
window.shopData = function () {
    var defaultData = {
        search: "",
        activeCategory: "Semua",
        categories: ["Semua"],
        products: [],
        isLoadingProducts: true,
        loadError: false,
        currentPage: 1,
        perPage: 12
    };
    return {
        search: defaultData.search,
        activeCategory: defaultData.activeCategory,
        categories: defaultData.categories,
        products: defaultData.products,
        isLoadingProducts: defaultData.isLoadingProducts,
        loadError: defaultData.loadError,
        currentPage: defaultData.currentPage,
        perPage: defaultData.perPage,
        async init() {
            this.isLoadingProducts = true;
            try {
                var res = await fetch("/feeds/posts/default/-/product?alt=json&maxResults=500");
                var json = await res.json();
                if (json.feed && json.feed.entry) {
                    var parsed = [];
                    for (var idx = 0; idx < json.feed.entry.length; idx++) {
                        try {
                            var entry = json.feed.entry[idx];
                            var content = entry.content && entry.content.$t ? entry.content.$t : "";
                            var parser = new DOMParser();
                            var doc = parser.parseFromString(content, "text/html");
                            var el = doc.querySelector(".ezy-meta");
                            if (!el) continue;
                            var raw = el.getAttribute("data-meta") || "{}";
                            var meta = JSON.parse(raw.replace(/&apos;/g, "\x27"));
                            if (meta._type !== "product") continue;
                            parsed.push({
                                id: meta.id || "",
                                name: meta.name || (entry.title ? entry.title.$t : "") || "",
                                slug: meta.slug || "",
                                price: Number(meta.price) || 0,
                                category: meta.category || "",
                                image: meta.image || "",
                                images: meta.images || [],
                                stock: Number(meta.stock) || 0,
                                compareatprice: Number(meta.compareatprice) || 0,
                                description: meta.description || "",
                                sku: meta.sku || "",
                                weight: Number(meta.weight) || 0,
                                weightunit: meta.weightunit || "gram",
                                publishedat: meta.publishedat || "",
                                _type: "product"
                            });
                        } catch (e) {/* skip */ }
                    }
                    this.products = parsed;
                    var catSet = {};
                    for (var ci = 0; ci < parsed.length; ci++) {
                        var pc = parsed[ci].category;
                        if (pc) catSet[pc] = true;
                    }
                    var cats = ["Semua"];
                    for (var ck in catSet) cats.push(ck);
                    this.categories = cats;
                }
                this.loadError = false;
            } catch (e) {
                console.warn("Shop fetch failed:", e);
                this.loadError = true;
            } finally {
                this.isLoadingProducts = false;
            }
        },
        get filteredProducts() {
            var result = this.products;
            if (this.activeCategory !== "Semua") {
                result = result.filter(function (p) { return p.category === this.activeCategory; }.bind(this));
            }
            if (this.search.trim()) {
                var q = this.search.toLowerCase();
                result = result.filter(function (p) { return p.name.toLowerCase().indexOf(q) !== -1 || p.category.toLowerCase().indexOf(q) !== -1; });
            }
            return result;
        },
        get paginatedProducts() {
            var start = (this.currentPage - 1) * this.perPage;
            return this.filteredProducts.slice(start, start + this.perPage);
        },
        get totalPages() {
            return Math.ceil(this.filteredProducts.length / this.perPage);
        },
        formatPrice: function (num) {
            return "Rp " + Number(num).toLocaleString("id-ID");
        }
    };
};

// 2. PRODUCT VIEW COMPONENT LOGIC
window.productViewData = function () {
    return {
        product: null,
        qty: 1,
        activeImage: 0,
        images: [],

        init: function () {
            var self = this;
            var meta = window._lastResolvedMeta;
            if (meta) {
                self.product = meta;
                // Gunakan images array jika ada, fallback ke image tunggal, lalu inisial
                self.images = (meta.images && meta.images.length > 0)
                    ? meta.images
                    : (meta.image ? [meta.image] : [(meta.title || meta.name || '?').substring(0, 2).toUpperCase()]);

                // Jika meta dari feed (tidak punya stock/description lengkap), fetch dari SSR page
                var needsFullData = (meta.stock === undefined || meta.stock === null || !meta.description);
                if (needsFullData && meta.slug) {
                    self.fetchFullMeta(meta.slug);
                }
            } else {
                self.product = { title: 'Produk Tidak Ditemukan', name: 'Produk Tidak Ditemukan', price: 0, description: 'Maaf, produk yang Anda cari tidak tersedia.' };
                self.images = ['??'];
            }

            // Update breadcrumb dengan judul produk setelah data siap
            if (window.app && typeof window.app.updateBreadcrumb === 'function') {
                window.app.updateBreadcrumb('product');
            }
        },

        fetchFullMeta: async function (slug) {
            var self = this;
            try {
                // Coba dari slugTypeMap cache untuk tahu URL
                var slugTypeMap = JSON.parse(localStorage.getItem('ezy_slug_type') || '{}');
                // Fetch dari Blogger feed untuk mendapatkan meta lengkap
                var res = await fetch('/feeds/posts/default/-/product?alt=json&maxResults=500');
                if (!res.ok) return;
                var json = await res.json();
                var entries = (json.feed && json.feed.entry) || [];
                for (var i = 0; i < entries.length; i++) {
                    try {
                        var content = (entries[i].content && entries[i].content.$t) ? entries[i].content.$t : '';
                        var doc = new DOMParser().parseFromString(content, 'text/html');
                        var el = doc.querySelector('.ezy-meta');
                        if (!el) continue;
                        var d = JSON.parse((el.getAttribute('data-meta') || '{}').replace(/&apos;/g, "'"));
                        if (d.slug !== slug && d.id !== slug) continue;
                        // Merge data lengkap ke product yang sudah ada
                        Object.assign(self.product, d);
                        self.images = (d.images && d.images.length > 0)
                            ? d.images
                            : (d.image ? [d.image] : [(d.name || '?').substring(0, 2).toUpperCase()]);
                        window._lastResolvedMeta = self.product;
                        break;
                    } catch (e) { }
                }
            } catch (e) { console.warn('[productView] fetchFullMeta failed:', e); }
        },

        formatPrice: function (num) {
            return 'Rp ' + Number(num).toLocaleString('id-ID');
        },

        addToCart: function () {
            if (!this.product) return;
            this.$store.cart.add({
                id: this.product.slug || this.product.id || 'unknown',
                name: this.product.title || this.product.name,
                price: this.product.price || 0,
                sku: this.product.sku || '',
                imageurl: this.product.image || '',
                images: this.product.images || []
            }, this.qty);
            this.qty = 1;
        },

        get discountPct() {
            var cp = Number(this.product && this.product.compareatprice) || 0;
            var p = Number(this.product && this.product.price) || 0;
            return (cp > 0 && cp > p) ? Math.round((1 - p / cp) * 100) : 0;
        },
        get hasDiscount() { return this.discountPct > 0; },
        get stockLabel() { return (Number(this.product && this.product.stock) || 0) > 0 ? 'Tersedia' : 'Stok Habis'; },
        get stockColor() { return (Number(this.product && this.product.stock) || 0) > 0 ? 'text-green-600' : 'text-red-600'; }
    };
};

window.voucherData = function () {
    return {
        vouchers: [
            { id: 'v1', label: 'Flash Sale Sparepart', disc: 'Rp25.000', min: 'Min. belanja Rp150.000', bg: 'bg-red-50 dark:bg-red-900/10 border-red-100 dark:border-red-900/20' },
            { id: 'v2', label: 'Diskon Member Baru', disc: '10%', min: 'Min. belanja Rp100.000', bg: 'bg-blue-50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-900/20' },
            { id: 'v3', label: 'Gratis Ongkir', disc: 'Rp0', min: 'Min. belanja Rp200.000', bg: 'bg-green-50 dark:bg-green-900/10 border-green-100 dark:border-green-900/20' }
        ],
        claimed: {}
    };
};

window.relatedProductsData = function () {
    return {
        relatedProducts: [],
        isLoadingRelated: true,
        init: async function () {
            var meta = window._lastResolvedMeta;
            if (!meta || !meta.category) { this.isLoadingRelated = false; return; }
            var currentSlug = meta.slug || meta.id || '';
            try {
                var res = await fetch('/feeds/posts/default/-/product?alt=json&maxResults=500');
                var json = await res.json();
                if (json.feed && json.feed.entry) {
                    var parsed = [];
                    for (var i = 0; i < json.feed.entry.length; i++) {
                        try {
                            var entry = json.feed.entry[i];
                            var content = (entry.content && entry.content.$t) ? entry.content.$t : '';
                            var doc = new DOMParser().parseFromString(content, 'text/html');
                            var el = doc.querySelector('.ezy-meta');
                            if (!el) continue;
                            var d = JSON.parse((el.getAttribute('data-meta') || '{}').replace(/&apos;/g, "'"));
                            if (d._type !== 'product' || d.slug === currentSlug || d.id === currentSlug) continue;
                            parsed.push({ id: d.id || '', name: d.name || (entry.title ? entry.title.$t : '') || '', slug: d.slug || '', price: Number(d.price) || 0, category: d.category || '', image: d.image || '', publishedat: d.publishedat || '' });
                        } catch (e) { }
                    }
                    this.relatedProducts = parsed.filter(function (p) { return p.category === meta.category; }).slice(0, 4);
                }
            } catch (e) {
                console.warn('Related fetch failed:', e);
            } finally {
                this.isLoadingRelated = false;
            }
        },
        formatPrice: function (num) { return 'Rp ' + Number(num).toLocaleString('id-ID'); }
    };
};